function maxFreeTime(eventTime, startTime, endTime) {
  const n = startTime.length;
  const gaps = [startTime[0]];
  for (let i = 1; i < n; i++) {
    gaps.push(startTime[i] - endTime[i - 1]);
  }
  gaps.push(eventTime - endTime[n - 1]);

  const rightMax = new Array(n + 2).fill(0);
  for (let g = n; g >= 0; g--) {
    rightMax[g] = Math.max(rightMax[g + 1], gaps[g]);
  }

  let leftMax = 0;
  let best = 0;
  for (let i = 0; i < n; i++) {
    const duration = endTime[i] - startTime[i];
    const merged = gaps[i] + gaps[i + 1];
    if (leftMax >= duration || rightMax[i + 2] >= duration) {
      best = Math.max(best, merged + duration);
    } else {
      best = Math.max(best, merged);
    }
    leftMax = Math.max(leftMax, gaps[i]);
  }
  return best;
}

