function maxFreeTime(eventTime, startTime, endTime) {
  // Try every legal spot for every meeting. Inside one free stretch the longest free run is largest when the
  // moved meeting is pushed against a neighbour or an end of the event, so only those starts need trying.
  const n = startTime.length;
  const meetings = startTime.map((s, i) => [s, endTime[i]]);
  const longestFree = (list) => {
    const sorted = list.slice().sort((a, b) => a[0] - b[0]);
    let longest = 0, time = 0;
    for (const [s, e] of sorted) { longest = Math.max(longest, s - time); time = Math.max(time, e); }
    return Math.max(longest, eventTime - time);
  };
  let best = longestFree(meetings);
  for (let i = 0; i < n; i++) {
    const length = endTime[i] - startTime[i];
    const others = meetings.filter((_, j) => j !== i);
    const starts = [0, eventTime - length];
    for (const [s, e] of others) starts.push(e, s - length);
    for (const start of starts) {
      if (start < 0 || start + length > eventTime) continue;
      if (others.some(([s, e]) => start < e && s < start + length)) continue;
      best = Math.max(best, longestFree([...others, [start, start + length]]));
    }
  }
  return best;
}

