function generate(rand, size) {
  const large = size === 'large';
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const n = large ? 2000 : 2 + Math.floor(rand() * 6);
  // Small inputs sometimes scale every time by 10^7 so that values near 10^9 appear too.
  const unit = !large && rand() < 0.15 ? 10000000 : 1;
  const longest = large ? pick([1000, 200000]) : 1 + Math.floor(rand() * 5);
  const widest = large ? pick([1000, 200000]) : pick([0, 1, 2, 4, 7]);
  const gap = () => (rand() < 0.25 ? 0 : Math.floor(rand() * (widest + 1))) * unit;
  const startTime = [], endTime = [];
  let time = 0;
  for (let i = 0; i < n; i++) {
    time += gap();
    startTime.push(time);
    time += (1 + Math.floor(rand() * longest)) * unit;
    endTime.push(time);
  }
  return [time + gap(), startTime, endTime];
}
